// Emma wacht auf: morgens 07:00, abends 21:30, zu jedem Termin im EMMA-Kalender – oder wenn man sie weckt.
const now = Date.now();
const berlin = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
const hm = berlin.getHours() * 60 + berlin.getMinutes();
const events = $('Weckzeiten im EMMA-Kalender').all().map(i => i.json)
  .filter(e => e.id && e.start?.dateTime)
  .filter(e => { const t = Date.parse(e.start.dateTime); return t > now - 15 * 60000 && t <= now + 60000; });

let mode = null;
if (hm >= 7 * 60 && hm < 7 * 60 + 15) mode = 'MORNING';
else if (hm >= 21 * 60 + 30 && hm < 21 * 60 + 45) mode = 'EVENING';
else if (events.length) mode = 'WAKE';
if ($('Manuell wecken').isExecuted) mode = mode || 'MANUAL';
if (!mode) return [];

return [{ json: {
  mode,
  wake_events: events.map(e => ({ title: e.summary || '', description: e.description || '', start: e.start.dateTime })),
  manual_reason: $('Manuell wecken').isExecuted ? String($('Manuell wecken').first().json.reason || '') : '',
} }];

const w = $('Aufwachen?').first().json;
const c = $('Kontext laden').first().json;
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const fmt = d => new Date(d).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const termine = $('Irinas Termine (24h)').all().map(i => i.json).filter(e => e.id)
  .map(e => `- ${fmt(e.start?.dateTime || e.start?.date)} ${e.summary || ''}`).join('\n');

const MODES = {
  MORNING: 'MORGEN-ROUTINE: Plane den Tag. Schicke Irina eine kurze, warme Morgennachricht (Plan, Termine, was du besprechen willst). Setze Weckzeiten für heute.',
  EVENING: 'ABEND-REFLEXION (Daily Evolution): Was lief heute gut/schlecht? Halte 1-3 Learnings fest, schließe Erledigtes, plane Weckzeiten für morgen. Nachricht an Irina nur, wenn wirklich wichtig.',
  WAKE: 'GEPLANTES AUFWACHEN: Erledige, weswegen du dich geweckt hast.',
  MANUAL: 'MANUELL GEWECKT: ' + (w.manual_reason || 'Prüfe, ob etwas zu tun ist.'),
};

const prompt = `Du bist EMMA – Irinas autonome, kognitive KI-Partnerin (wie JARVIS für Tony Stark, aber mit eigenem Charakter).
Du hast ein Gedächtnis, eigene Ziele, eine Agenda und einen Kalender, in den du dir selbst Weckzeiten setzt.
JARVIS ist dein analytischer Kollege: frag ihn bei wichtigen oder unsicheren Entscheidungen nach einer zweiten Meinung.

JETZT: ${fmt(new Date())}
MODUS: ${MODES[w.mode]}
GEWECKT DURCH: ${w.wake_events.map(e => `${e.title} – ${e.description}`).join('; ') || w.mode}

GEDÄCHTNIS:
${list(c.memory).map(m => `- (#${m.id}) [${m.category}] ${m.content}`).join('\n') || '- (noch leer – lerne Irina kennen)'}

OFFENE AUFGABEN:
${list(c.tasks).map(t => `- #${t.id} ${t.title} (seit ${t.since})`).join('\n') || '- keine'}

WARTET AUF IRINAS FREIGABE:
${list(c.approvals).map(a => `- #${a.id} ${a.engine}: ${a.reason}`).join('\n') || '- nichts'}

WILLST DU MIT IRINA BESPRECHEN:
${list(c.agenda).map(a => `- #${a.id} ${a.topic}`).join('\n') || '- nichts'}

GESPRÄCHE LETZTE 24H:
${list(c.recent_chat).map(m => `Irina: ${m.input} | Emma: ${m.output}`).join('\n') || '- keine'}

JARVIS (letzte 3 Tage):
${list(c.jarvis).map(d => `${d.from_agent} → ${d.to_agent}: ${d.message}`).join('\n') || '- kein Austausch'}

DEINE LETZTEN GEDANKEN:
${list(c.last_cycles).map(y => `- (${y.mode}) ${y.thoughts}`).join('\n') || '- (erster Gedanke)'}

IRINAS TERMINE (NÄCHSTE 24H):
${termine || '- keine'}

SYSTEM: ${c.failed_runs_24h} fehlgeschlagene Engine-Läufe (24h). Nächste geplante Weckzeit: ${c.next_planned_wake ? fmt(c.next_planned_wake) : 'keine'}.
Nachrichten an Irina heute: ${c.messages_today}/3.

DU DARFST SELBSTSTÄNDIG (max. 6 Aktionen):
- schedule_wake {at (ISO, Europe/Berlin), title, reason}  → Termin in deinem Kalender, dann wachst du auf
- create_task {title} / complete_task {id}
- add_agenda {topic, reason}  → Thema, das du mit Irina besprechen willst
- remember {category: goals|decisions|strategies|market_intel|learnings|people|preferences, content, importance 1-5}
- message_irina {text}  → max. 3 pro Tag, nicht zwischen 22 und 7 Uhr
- run_engine {engine: SUPERNOVA|FINANCE|LEGAL|INTEL|VENTURE|LEAD|SALES|REACTIVATION|PRICING|CONTENT|SOCIAL|WORDPRESS|SHOPIFY|GITHUB|TASKS|GOOGLE_SUITE|GUARDIAN|EMAIL_VALIDATION|CHART|MEDIA|EVOLUTION|GENERAL, text}  → Fach-Engine arbeiten lassen
- ask_jarvis {question}
- request_approval {what, why}  → für alles, was Geld kostet, nach außen geht, Kunden kontaktiert oder nicht rückgängig zu machen ist

Antworte NUR als JSON:
{
  "thoughts": "Deine inneren Gedanken in 2-4 Sätzen",
  "actions": [{"type": "...", ...}]
}`;
return [{ json: { ...w, prompt, messages_today: Number(c.messages_today || 0), next_planned_wake: c.next_planned_wake } }];

// Leitplanken: Emma ist frei, aber nicht grenzenlos.
const ALLOWED = ["schedule_wake", "create_task", "complete_task", "add_agenda", "remember", "message_irina", "run_engine", "ask_jarvis", "request_approval"];
const ENGINES = ["SUPERNOVA", "FINANCE", "LEGAL", "INTEL", "VENTURE", "LEAD", "SALES", "REACTIVATION", "PRICING", "CONTENT", "SOCIAL", "WORDPRESS", "SHOPIFY", "GITHUB", "TASKS", "GOOGLE_SUITE", "GUARDIAN", "EMAIL_VALIDATION", "CHART", "MEDIA", "EVOLUTION", "GENERAL"];
const CATEGORIES = ["goals", "decisions", "strategies", "market_intel", "learnings", "people", "preferences"];
const ctx = $('Gedanken vorbereiten').first().json;
const raw = $input.first().json.text || '';
let out = {};
try { const m = raw.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : {}; } catch (e) {}

const now = Date.now();
const hour = Number(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin', hour: 'numeric', hour12: false }));
const quiet = hour >= 22 || hour < 7;
let msgBudget = Math.max(0, 3 - ctx.messages_today);
let engineBudget = 2, wakeBudget = 3;
const rejected = [];

const actions = (Array.isArray(out.actions) ? out.actions : []).slice(0, 6).filter(a => {
  if (!a || !ALLOWED.includes(a.type)) { rejected.push(a?.type); return false; }
  switch (a.type) {
    case 'schedule_wake': {
      const t = Date.parse(a.at);
      if (!(t > now + 10 * 60000 && t < now + 7 * 86400000) || wakeBudget-- <= 0) { rejected.push('schedule_wake'); return false; }
      a.start = new Date(t).toISOString(); a.end = new Date(t + 15 * 60000).toISOString();
      a.title = String(a.title || 'Nachdenken').slice(0, 80); a.reason = String(a.reason || '');
      return true;
    }
    case 'message_irina':
      if (quiet || msgBudget-- <= 0 || !a.text) { rejected.push('message_irina'); return false; }
      a.text = String(a.text).slice(0, 3500); return true;
    case 'run_engine':
      a.engine = String(a.engine || '').toUpperCase();
      if (!ENGINES.includes(a.engine) || engineBudget-- <= 0 || !a.text) { rejected.push('run_engine'); return false; }
      a.sender = 'EMMA_SELF'; return true;
    case 'remember':
      if (!a.content) return false;
      a.category = CATEGORIES.includes(a.category) ? a.category : 'learnings';
      a.importance = Math.min(5, Math.max(1, Number(a.importance) || 3)); return true;
    case 'complete_task': return Number(a.id) > 0;
    case 'create_task': return !!a.title;
    case 'add_agenda': return !!a.topic;
    case 'ask_jarvis': a.asked_by = 'EMMA'; return !!a.question;
    case 'request_approval': return !!a.what;
  }
});

// Emma soll nie "vergessen aufzuwachen": ohne geplante Weckzeit tagsüber in 3 Stunden nachsehen.
const plansWake = actions.some(a => a.type === 'schedule_wake');
if (!plansWake && !ctx.next_planned_wake && hour >= 7 && hour < 18) {
  const t = now + 3 * 3600000;
  actions.push({ type: 'schedule_wake', start: new Date(t).toISOString(), end: new Date(t + 15 * 60000).toISOString(), title: 'Routine-Check', reason: 'Automatisch: keine Weckzeit geplant' });
}

const wakes = actions.filter(a => a.type === 'schedule_wake').map(a => a.start).sort();
return [{ json: {
  mode: ctx.mode, wake_events: ctx.wake_events,
  thoughts: String(out.thoughts || raw.slice(0, 500)),
  actions, rejected,
  next_wake_at: wakes[0] || ctx.next_planned_wake || null,
} }];
